using System;using System.IO;using System.Collections.Generic;using System.Linq;using System.Text;using System.Security.Cryptography;
partial class FuaNative {
 Dictionary<string,object> PreviewSettings(){try{return json.Deserialize<Dictionary<string,object>>(File.ReadAllText(DataFile("preview-settings.json")));}catch{return new Dictionary<string,object>();}}
 int PreviewLimit(Dictionary<string,object> d,string key,int fallback,int minimum,int maximum){try{return Math.Max(minimum,Math.Min(maximum,Convert.ToInt32(d[key])));}catch{return fallback;}}
 string ExternalRecord(string file){using(var sha=SHA256.Create()){string key=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(file).ToLowerInvariant()))).Replace("-","").ToLowerInvariant();string dir=DataFile("external-history");Directory.CreateDirectory(dir);return Path.Combine(dir,key+".json");}}
 double ExternalResume(string file){try{var f=new FileInfo(file);var d=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(ExternalRecord(file)));if(Convert.ToInt64(d["size"])!=f.Length||Convert.ToInt64(d["mtime"])!=f.LastWriteTimeUtc.Ticks||Convert.ToBoolean(d["watched"]))return 0;return Math.Max(0,Convert.ToDouble(d["position"]));}catch{return 0;}}
 void SaveExternal(){if(!standalone||mpv==IntPtr.Zero||!ready||string.IsNullOrEmpty(current))return;try{double position=Number("time-pos")*1000,duration=Number("duration")*1000;if(duration<=0||position<1000)return;var f=new FileInfo(current);bool watched=position>=(duration>240000?duration-120000:duration*.95);string target=ExternalRecord(current),temp=target+"."+System.Diagnostics.Process.GetCurrentProcess().Id+".tmp";File.WriteAllText(temp,json.Serialize(new{file=current,size=f.Length,mtime=f.LastWriteTimeUtc.Ticks,position=position,duration=duration,watched=watched,updated=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}));if(File.Exists(target))File.Delete(target);File.Move(temp,target);int limit=PreviewLimit(PreviewSettings(),"maxHistoryMedia",200,10,10000);foreach(var old in new DirectoryInfo(Path.GetDirectoryName(target)).GetFiles("*.json").OrderByDescending(x=>x.LastWriteTimeUtc).Skip(limit))old.Delete();}catch{}}
}
